def rows(raw, avg30):
    out = []
    for ts, size, price, premium, ask, bid, ext, cond, volume in raw:
        out.append({
            "executed_at": ts, "created_at": ts, "size": size, "price": price,
            "premium": premium, "nbbo_ask": ask, "nbbo_bid": bid,
            "ext_hour_sold_codes": ext, "sale_cond_codes": cond,
            "avg30_volume": avg30, "volume": volume,
            "canceled": False, "ticker": "?",
        })
    return out


def qrtx():
    """An ordinary liquid mid-cap -- the contrast that broke the v1 floor."""
    return rows(QRTX, QRTX_AVG30)


def acme():
    return rows(ACME, ACME_AVG30)


def zeno():
    return rows(ZENO, ZENO_AVG30)
